// Lấy tối đa 5 sản phẩm mới nhất, dựng 1 đoạn nội dung cho bài đăng OA.
const items = ($input.first().json.products || []).slice(0, 5);
const shop = $vars.SHOPIFY_STORE_URL || 'https://noithatgotunhien-ulife.com';
function vnd(v){ const n = Number(v||0); return n ? n.toLocaleString('vi-VN') + 'đ' : 'liên hệ'; }
const lines = items.map(p => {
  const price = (p.variants && p.variants[0] && p.variants[0].price) || 0;
  return `• ${p.title} — ${vnd(price)}`;
});
const text = `🌿 ULIFe — Mẫu nội thất gỗ thông tự nhiên mới\n\n` +
  lines.join('\n') +
  `\n\nĐặt làm theo yêu cầu cho quán cà phê, nhà hàng & gia đình.\n` +
  `Xem thêm: ${shop}\n☎️ 0815 006 531 (8h–18h)`;
const firstImg = (items[0] && items[0].image && items[0].image.src) || '';
return [{ json: { oa_text: text, image_url: firstImg, count: items.length } }];
